Select PFM_VALD_Group.VALDGroupId, PFM_VALD_Page.VALDPageId, PFM_VALD_Rule_PFM_VALD_Group_R.VALDRuleId into #TempValidationBeforeFilter FROM PFM_VALD_Page INNER JOIN PFM_VALD_Page_PFM_VALD_Group_R ON PFM_VALD_Page_PFM_VALD_Group_R.VALDPageId = PFM_VALD_Page.VALDPageId Inner Join PFM_VALD_Group ON PFM_VALD_Group.VALDGroupId = PFM_VALD_Page_PFM_VALD_Group_R.VALDGroupId INNER JOIN PFM_VALD_Rule_PFM_VALD_Group_R ON PFM_VALD_Rule_PFM_VALD_Group_R.VALDGroupId=PFM_VALD_Group.VALDGroupId
except Select VALDGroupId,VALDPageId,VALDRuleId from dbo.PFM_VALD_Exception where ResourceValue = and ResourceType =
Select PFM_VALD_Page.VALDPageId ,PFM_VALD_Page.PageName from PFM_VALD_Page where PFM_VALD_Page.VALDPageId in (Select VALDPageId from #TempValidationBeforeFilter)
